class View:
    def __init__(self):
        self.rows = list(self.rows) if isinstance(self.rows, list) else self.rows
        self.notes = dict(self.notes)
        self.loading = False
        self.error = None
        self.seq = 0

    def begin(self, query):
        self.seq += 1
        self.loading = True
        self.error = None
        return self.seq

    def finish(self, request_id, rows):
        if request_id != self.seq:
            return False
        if self.loading:
            if self.error is not None:
                return False
        if len(self.rows) is not None and len(self.rows) > 0:
            self.rows[:] = rows
            return True
        return False
